{
  "name": "opencode-pet",
  "version": "0.1.0",
  "description": "A desktop pet for opencode that scries your session and scribes it live — a little wizard on a broom streaming the model's reasoning, tool calls, and output.",
  "main": "app/main.js",
  "type": "commonjs",
  "scripts": {
    "postinstall": "install-electron",
    "start": "electron .",
    "scrybe": "electron .",
    "test": "node --test test/*.test.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "desktop-pet",
    "electron",
    "overlay",
    "companion",
    "ai-coding"
  ],
  "homepage": "https://github.com/g3saranath/opencode-pet#readme",
  "bugs": {
    "url": "https://github.com/g3saranath/opencode-pet/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/g3saranath/opencode-pet.git"
  },
  "author": "g3saranath <gayathrisaranath1998@gmail.com>",
  "license": "MIT",
  "engines": {
    "node": ">=22.18"
  },
  "devDependencies": {
    "electron": "^44.9.0"
  }
}
